test.describe("seeded learner state", () => {
	test("seedLearnedVocabulary produces a learner the app really sees", async ({
		page,
	}) => {
		const knownWords = await seedLearnedVocabulary(page, 150);
		expect(knownWords).toHaveLength(150);

